#!/bin/sh
# Offline native Android build using installed SDK tools; no Gradle daemon or downloads.
set -eu
PROJECT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
SDK_DIR=${ANDROID_SDK_ROOT:-${ANDROID_HOME:-$HOME/Library/Android/sdk}}
JAVA_DIR=${JAVA_HOME:-/Applications/Android Studio.app/Contents/jbr/Contents/Home}
BUILD_TOOLS_VERSION=${BUILD_TOOLS_VERSION:-36.0.0}
ANDROID_PLATFORM=${ANDROID_PLATFORM:-android-37.0}
TOOLS_DIR="$SDK_DIR/build-tools/$BUILD_TOOLS_VERSION"
ANDROID_JAR="$SDK_DIR/platforms/$ANDROID_PLATFORM/android.jar"
BUILD_DIR="$PROJECT_DIR/build/local"
for path in "$JAVA_DIR/bin/javac" "$TOOLS_DIR/aapt2" "$ANDROID_JAR"; do
  if [ ! -e "$path" ]; then echo "Required installed tool missing: $path" >&2; exit 1; fi
done
# Recreate generated bytecode so removed or renamed sources cannot survive in an APK.
rm -rf "$BUILD_DIR/classes" "$BUILD_DIR/dex" "$BUILD_DIR/test-classes" "$BUILD_DIR/generated"
mkdir -p "$BUILD_DIR/classes" "$BUILD_DIR/dex" "$BUILD_DIR/test-classes" "$PROJECT_DIR/app/build/outputs/apk/debug"
"$TOOLS_DIR/aapt2" compile --dir "$PROJECT_DIR/app/src/main/res" -o "$BUILD_DIR/resources.zip"
"$TOOLS_DIR/aapt2" link -o "$BUILD_DIR/unsigned.apk" -I "$ANDROID_JAR" --manifest "$PROJECT_DIR/app/src/main/AndroidManifest.xml" -A "$PROJECT_DIR/app/src/main/assets" --min-sdk-version 28 --target-sdk-version 35 --version-code 1 --version-name 0.1.0-prototype --java "$BUILD_DIR/generated" "$BUILD_DIR/resources.zip"
find "$PROJECT_DIR/app/src/main/java" "$BUILD_DIR/generated" -name '*.java' -print > "$BUILD_DIR/sources.txt"
"$JAVA_DIR/bin/javac" -encoding UTF-8 --release 8 -classpath "$ANDROID_JAR" -d "$BUILD_DIR/classes" @"$BUILD_DIR/sources.txt"
"$JAVA_DIR/bin/jar" cf "$BUILD_DIR/classes.jar" -C "$BUILD_DIR/classes" .
"$JAVA_DIR/bin/java" -cp "$TOOLS_DIR/lib/d8.jar" com.android.tools.r8.D8 --lib "$ANDROID_JAR" --min-api 28 --output "$BUILD_DIR/dex" "$BUILD_DIR/classes.jar"
(cd "$BUILD_DIR/dex" && zip -q -u "$BUILD_DIR/unsigned.apk" classes.dex)
"$TOOLS_DIR/zipalign" -f 4 "$BUILD_DIR/unsigned.apk" "$BUILD_DIR/aligned.apk"
if [ ! -f "$BUILD_DIR/debug.jks" ]; then
  "$JAVA_DIR/bin/keytool" -genkeypair -keystore "$BUILD_DIR/debug.jks" -storepass android -keypass android -alias androiddebugkey -keyalg RSA -keysize 2048 -validity 3650 -dname 'CN=SCENIC Debug,O=Prototype,C=KR' >/dev/null
fi
"$JAVA_DIR/bin/java" -jar "$TOOLS_DIR/lib/apksigner.jar" sign --ks "$BUILD_DIR/debug.jks" --ks-key-alias androiddebugkey --ks-pass pass:android --key-pass pass:android --out "$PROJECT_DIR/app/build/outputs/apk/debug/scenic-debug.apk" "$BUILD_DIR/aligned.apk"
"$JAVA_DIR/bin/java" -jar "$TOOLS_DIR/lib/apksigner.jar" verify --verbose "$PROJECT_DIR/app/build/outputs/apk/debug/scenic-debug.apk"
"$JAVA_DIR/bin/javac" -encoding UTF-8 -d "$BUILD_DIR/test-classes" "$PROJECT_DIR/app/src/main/java/com/scenic/pleos/CourseEngine.java" "$PROJECT_DIR/app/src/main/java/com/scenic/pleos/NationwideCatalog.java" "$PROJECT_DIR/app/src/main/java/com/scenic/pleos/LocationFixPolicy.java" "$PROJECT_DIR/tests/CourseEngineTest.java" "$PROJECT_DIR/app/src/main/java/com/scenic/pleos/VehicleSafety.java" "$PROJECT_DIR/app/src/test/java/com/scenic/pleos/VehicleSafetyTest.java"
"$JAVA_DIR/bin/java" -cp "$BUILD_DIR/test-classes" com.scenic.pleos.CourseEngineTest
"$JAVA_DIR/bin/java" -cp "$BUILD_DIR/test-classes" com.scenic.pleos.VehicleSafetyTest
"$JAVA_DIR/bin/javac" -encoding UTF-8 --release 8 -d "$BUILD_DIR/test-classes" "$PROJECT_DIR/app/src/main/java/com/scenic/pleos/ApiRequestGate.java" "$PROJECT_DIR/tests/ApiRequestGateTest.java" "$PROJECT_DIR/app/src/main/java/com/scenic/pleos/RouteProjection.java" "$PROJECT_DIR/tests/RouteProjectionTest.java"
"$JAVA_DIR/bin/java" -cp "$BUILD_DIR/test-classes" com.scenic.pleos.ApiRequestGateTest
"$JAVA_DIR/bin/java" -cp "$BUILD_DIR/test-classes" com.scenic.pleos.RouteProjectionTest
"$JAVA_DIR/bin/javac" -encoding UTF-8 --release 8 -d "$BUILD_DIR/test-classes" "$PROJECT_DIR/app/src/main/java/com/scenic/pleos/LocationFixPolicy.java" "$PROJECT_DIR/tests/LocationFixPolicyTest.java"
"$JAVA_DIR/bin/java" -cp "$BUILD_DIR/test-classes" com.scenic.pleos.LocationFixPolicyTest
"$JAVA_DIR/bin/javac" -encoding UTF-8 --release 8 -d "$BUILD_DIR/test-classes" "$PROJECT_DIR/app/src/main/java/com/scenic/pleos/ScenicLayoutPolicy.java" "$PROJECT_DIR/tests/ScenicLayoutPolicyTest.java"
"$JAVA_DIR/bin/java" -cp "$BUILD_DIR/test-classes" com.scenic.pleos.ScenicLayoutPolicyTest
printf '\nAPK: %s\n' "$PROJECT_DIR/app/build/outputs/apk/debug/scenic-debug.apk"
